mapper.select:
SELECT id, workspace_id, kind, title, status, created_at, updated_at
FROM ainer_knowledge_object
WHERE workspace_id = #{workspaceId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT id, object_id, revision_number, payload_markdown, status, created_by_issuer,
       created_by_type, created_by_id, created_at, published_at
FROM ainer_knowledge_revision WHERE id = #{id}

mapper.update:
UPDATE ainer_knowledge_revision
SET status = 'PUBLISHED', published_at = #{at}
WHERE id = #{id} AND status = 'PROPOSED'
